    "summary": "川久保玲が率いる、既存の「美しさ」や「服の形」を問い直し続けるブランド。多数のラインを持ち、渡辺淳弥や阿部千登勢など多くのデザイナーを輩出した。",
    "about": "COMME des GARÇONS（コム デ ギャルソン、フランス語で「少年のように」）は、川久保玲が1969年に東京で服を作り始め、1973年に株式会社化したブランド。服飾の専門教育を受けていない川久保が、スタイリストの仕事の中で「着たい服がない」と感じたことが出発点だった。最初は日本の女性のための服で、1975年に東京で最初のコレクションを発表し、1978年にメンズのHOMMEを始めた。\n1981年、山本耀司とともにパリ・コレクションに参加した。黒を中心に、穴をあけ、ほつれさせ、左右非対称に、身体の線を隠すように作った服は、欧米のプレスに「ボロルック」「ヒロシマ・シック」と書かれ、酷評と熱狂の両方を巻き起こした。この「黒の衝撃」は、装飾と身体の美しさを当然とする西洋のモードに対する根本的な問いかけであり、日本のデザイナーが世界のファッションの中心に立つ時代の始まりとなった。1980年代の日本では「カラス族」と呼ばれる黒ずくめの若者を生み、DCブランドブームの象徴にもなった。\nCOMME des GARÇONSの作風はシーズンごとに大きく変わるが、一貫しているのは「新しいものを作る」ことと、「美しい」「女らしい」「服とはこういうもの」という前提を疑うこと。1997年春夏の「Body Meets Dress, Dress Meets Body」（詰め物で身体の形そのものを変えた通称「こぶドレス」）、2012年春夏の平面（2D）の服、2014年春夏以降の、着ることを前提にしない彫刻のようなオブジェなど、服の概念を広げる作品を発表し続けている。赤いバラ、ポルカドット、花柄、極端なオーバーサイズも繰り返し現れるモチーフ。ショーの後に言葉で説明することはほとんどない。\nブランドとしての最大の特徴は、ひとつの会社の中に多数のラインを持つこと。COMME des GARÇONS（メインのウィメンズ）、HOMME（1978年、ワークやミリタリーを下敷きにした日常着）、HOMME PLUS（1984年、パリで発表するメンズのコレクション）、tricot（ニット）、COMME des GARÇONS SHIRT（1988年、シャツ）、Homme Deux（スーツ）、PLAY（2002年、ハートに目のロゴ）、BLACK（2009年）、COMME des GARÇONS GIRLなど、性格の違うラインがある。さらに、渡辺淳弥（JUNYA WATANABE）、栗原たお（tao）、二宮啓（noir kei ninomiya）ら社内のデザイナーに自分の名前のブランドを持たせ、阿部千登勢（sacai）、阿部潤一（kolor）なども同社から巣立った。HOMMEは1990年代に田中啓一、2000年代以降は渡辺淳弥がデザインした時期があり、デザイナーによって雰囲気が大きく異なる。\n2004年にはロンドンに、複数のブランドを一つの建物に集めた複合店「Dover Street Market」を開き、銀座、ニューヨーク、北京、ロサンゼルスなどにも広げた。NIKE、Supreme、Louis Vuitton、Converse（PLAYのハートのスニーカー）などとの協業も多い。2017年にはメトロポリタン美術館で存命のデザイナーとしては2人目となる大規模な個展が開かれた。\n古着でCOMME des GARÇONSを見るときは、タグのAD表記（例：AD1999は1999年製）が年代の目安になる（1988年頃以降）。タグのデザインや素材表示の書式でも年代を推測できる。1980年代前半の黒くほつれた服、1990年代前半のHOMMEの田中啓一期、HOMME PLUSの縮絨やポリエステルの縮み加工のテーラリング（1994〜2002年頃）、1997年春夏のこぶドレス周辺、2000年代前半のプリントのシャツやジャケットなどが特に人気が高い。",
