    "summary": "COMME des GARÇONSのパタンナー出身・渡辺淳弥のブランド。テクニカルな素材や構造、既存ブランドとのコラボレーションによる再構築が得意。",
    "about": "JUNYA WATANABE COMME des GARÇONSは、COMME des GARÇONSのパタンナー出身の渡辺淳弥が1992年に始めた、COMME des GARÇONS社の中のブランド。川久保玲のもとで、ニットのライン「tricot COMME des GARÇONS」のデザインを経験したのち、自身の名前のウィメンズを東京で発表し、翌1993年からパリ・コレクションに参加した。\nウィメンズの特徴は、パターンと素材の徹底的な実験。透けるオーガンジーやチュールを何層にも重ねた造形、ハニカム（蜂の巣）状に折りたたんで広げると立体になる生地、防水素材やナイロン、ポリウレタンなどテクニカルな素材を使った服、デニムやパッチワークの再構築などで、毎シーズン高い評価を受けている。川久保の作品が「問い」だとすれば、渡辺の作品は「技術による答え」と語られることもある。\n2001年に始めたメンズの「JUNYA WATANABE COMME des GARÇONS MAN」では、Levi's、Carhartt、The North Face、New Balance、Brooks Brothers、Barbour、Karrimor、Moncler、Converse、Seil Marschallなど、アメリカやイギリスのワーク、アウトドア、ミリタリー、トラッドの定番ブランドと組み、パッチワーク、切り替え、素材の置き換えで再構築した服を毎シーズン発表している。どこにでもある「実用の服」を素材にしながら、どこにもない一着にするこの手法は、のちのストリートとラグジュアリーの協業の流行を先取りしていた。2005年にはeYeライン（eYe JUNYA WATANABE MAN）も始めた。\n古着では、メンズのパッチワークのデニム、Levi'sとのリメイクのジーンズやジャケット、The North Faceとのアウター、Carharttとのワークジャケット、ウィメンズの2000年前後の実験的なシーズンのドレスやジャケットが人気。COMME des GARÇONS社のブランドなので、タグのAD表記で年代がわかる。協業のアイテムは、相手のブランドのタグも付いていることが多い。",
