    "dating": [
      {
        "title": "タグと品番",
        "text": "タグのデザイン（ロゴの書体や色）、品番の書式、品質表示の会社名の表記の変化から、おおよその年代がわかる。1980年代には「Y's for men」のタグのメンズもある。年代ごとのタグの写真を集めて比べるのが確実。"
      }
    ],
    "eras": [
      {
        "name": "Y's 期（東京初期）",
        "from": 1972,
        "to": 1980,
        "d": "yamamoto",
        "text": "山本耀司が Y's を始め、1977年に東京で初のショーを行った時代。ゆったりした女性服で、働く女性のための「男物のような服」を作った。",
        "works": [
          "初期 Y's のコート・パンツ"
        ]
      },
      {
        "name": "80年代（黒の衝撃）",
        "from": 1981,
        "to": 1989,
        "d": "yamamoto",
        "text": "1981年にパリで発表を始めた時代。黒、ゆったりした形、非対称の裾など、川久保玲とともに「黒の衝撃」と呼ばれた。1984年にヨウジヤマモト プールオムを始める。80年代の服はウールギャバジンや綿の厚手の生地が多く、今も人気が高い。",
        "works": [
          "ウールギャバジンのコート・セットアップ",
          "初期プールオムのジャケット",
          "1986-87年秋冬（クリスチャン・ディオールへのオマージュ）"
        ]
      },
      {
        "name": "90年代（テーラード・ウェディング期）",
        "from": 1990,
        "to": 1999,
        "d": "yamamoto",
        "text": "1991-92年秋冬のウェディングドレスのショー、木の板や大きな帽子を使ったショーなど、詩的な演出が評価された時代。プールオムではレーヨン、ギャバジン、ウールの柔らかいテーラードジャケットやワイドパンツが定番になり、古着では「90年代のプールオム」が特に人気が高い。",
        "works": [
          "ウェディングドレスのショー（1991-92年秋冬）",
          "レーヨン・ギャバジンのジャケット",
          "ワイドパンツ",
          "1990年代のプールオムのシャツ"
        ]
      },
      {
        "name": "Y-3・2000年代",
        "from": 2000,
        "to": 2009,
        "d": "yamamoto",
        "text": "2002年に adidas と Y-3 を始め、スポーツとモードを結びつけた時代。メインのコレクションは、より自由で前衛的な表現になった。2009年に会社が経営難に陥り、投資会社の支援で立て直した。",
        "works": [
          "Y-3（2002年〜）",
          "2003年春夏（ウィメンズ）"
        ]
      },
      {
        "name": "2010年代以降",
        "from": 2010,
        "to": null,
        "d": "yamamoto",
        "text": "経営の立て直しのあと、Ground Y、S'YTE など若い世代向けのラインを増やした時代。メインラインでは、アーティストの絵や言葉をプリントした服、作務衣のようなテーラードなどが続いている。",
        "works": [
          "Ground Y・S'YTE のアイテム",
          "プリントのシャツ・コート"
        ]
      }
    ]
