      "シーズンタイトルと品番・タグを照合して年代を判断する。",
      "裏原宿期（1990年代）・東京コレクション期（〜2002）・パリ期で、ターゲットも作りも違う。",
      "2014-15AW以降はメンズとウィメンズでタイトルが別になる。"
