    "note": "1997〜1999年のタイトル（RELIEF / EXCHANGE / AMBIVALENCE / LEAF / DRAPE）は資料によってシーズンの割り当てが食い違います。ここでは複数資料が一致するものを採用しました。表にないシーズンは今回の調査でタイトルを確認できなかったものです。",
