    "summary": "NUMBER (N)INEを離れた宮下貴裕が2010年に始めたブランド。より個人的でテーラリングの効いた作風。宮下は2025年7月、15周年を節目にブランドを離れた。",
    "about": "TAKAHIROMIYASHITA TheSoloist.は、NUMBER (N)INEを離れた宮下貴裕が2010年に始めたブランド。「独奏者」を意味する名前の通り、宮下個人の世界観をより純粋に表現する場として始まった。\nNUMBER (N)INEのロックな感覚を引き継ぎつつ、TheSoloist.の服は、より個人的で、内省的で、緻密なものになった。テーラリングの効いたジャケットやコート、ミリタリーやワークウェアの再構築、左右非対称で片側だけに付いたディテール（片方の袖だけのポケットなど）、リバーシブルの服、細身のシルエットが特徴。音楽や文学、宮下自身の記憶が着想源になっている。\n2015年頃からはパリで発表し、海外でも評価を高めた。CONVERSE、NIKE、Dickiesなどとの協業も知られる。\n宮下は2025年7月、15周年を節目にブランドを離れ、同年NUMBER (N)INEとして再始動した。古着では、2010年代のテーラリングのジャケットやコート、ミリタリーのアウターが人気。",
    "history": [
      {
        "year": 2010,
        "text": "TAKAHIROMIYASHITA TheSoloist.を開始"
      },
      {
        "year": 2018,
        "text": "1月、ピッティ・ウオモでUNDERCOVERと共にゲストデザイナーとしてショー"
      },
      {
        "year": 2025,
        "text": "7月、宮下が2025-26年秋冬を最後に離脱を発表（「創造的な再出発」）"
      }
    ],
