        "d": "nigo",
        "text": "NIGO が高橋盾と原宿に「NOWHERE」を開き、その中で A BATHING APE を始めた時代。映画『猿の惑星』の猿の顔、ABC カモ（迷彩）などで、裏原宿ブームの中心になった。生産数を少なくしたことで人気が過熱した。",
