    "summary": "北村信彦が21歳で、入社したオゾンコミュニティで1984年に始めたブランド。60〜70年代のロックやポップアートを東京的に再解釈。",
    "about": "HYSTERIC GLAMOUR（ヒステリックグラマー）は、北村信彦が21歳で入社したアパレル会社オゾンコミュニティで、1984年に始めたブランド。\nHYSTERIC GLAMOURは、1960〜70年代のロック、ポップアート、アメリカのB級映画やコミック、ピンナップガール、ポルノ雑誌的なグラフィックを、東京のロックな女の子のための服として再解釈した。目の大きな女の子「ヒスガール」のグラフィックのTシャツ、ブランケット柄（毛布のような柄）のアイテム、加工したデニム、レオパードやハートの柄、ロックバンドのTシャツ風のデザインが代表的。\n写真や音楽、アートとの関わりも深く、荒木経惟、森山大道、テリー・リチャードソンらとの写真集やコラボ、アンディ・ウォーホル財団とのコラボを数多く手がけた。ソニック・ユースのキム・ゴードンなど海外のミュージシャンにも愛用され、1990年代の東京のストリートを代表するブランドとなった。メンズとウィメンズ、子ども服（HYSTERIC MINI）も展開する。\n古着では、1990年代のガールのグラフィックTシャツ、デニム、レザー、ブランケット柄のアイテムが人気で、近年は海外のヴィンテージ市場で特に評価が高い。",
    "history": [
      {
        "year": 1984,
        "text": "東京モード学園を卒業した北村信彦が、オゾンコミュニティでHYSTERIC GLAMOURを立ち上げる"
      }
    ],
