    "summary": "1837年にパリで始まった馬具工房。馬具の技術を生かした革製品（ケリー、バーキン）とシルクのスカーフで知られる。ウィメンズのプレタポルテではマルジェラ、ゴルチエ、ルメール、ナデージュ・ヴァンヘ＝シビュルスキと意外な人選が続き、メンズは37年続いたヴェロニク・ニシャニアンの時代が2026年1月に終わり、グレース・ウェールズ・ボナーに。",
    "about": "Hermès（エルメス）は、1837年にティエリ・エルメスがパリで始めた馬具の工房。馬車のための丈夫で美しい馬具（ハーネス）を作っていたが、自動車の時代が来ると、その革の技術と、馬具に使われる「サドルステッチ」（2本の針で手で縫う技法）を、バッグ、旅行かばん、ベルト、手袋、時計のベルトなどに生かした。1880年にフォーブル・サントノレ通り24番地に移り、ここが今も本店となっている。\n1922年に最初のハンドバッグ、1937年にシルクのスカーフ「カレ（90cm角）」、1949年にネクタイを発表した。代表的なバッグは、1935年の「サック・ア・デペッシュ」を原型とし、1956年にグレース・ケリーが妊娠を隠すために持った写真で有名になって1977年に正式に改名された「ケリー」、1984年に女優ジェーン・バーキンと社長ジャン＝ルイ・デュマの機内での出会いから生まれた「バーキン」。どちらも今も熟練の職人がひとりで一つを仕上げ、入手が非常に難しいことで知られる。コンスタンス（1959年）、エブリン（1978年）、ピコタンなども人気。\nHermèsは、ロゴを前面に出さず、素材と仕立てで価値を示す姿勢が一貫している。オレンジの箱、馬車と従者のロゴも象徴的。創業家による経営を長く守り、2010年頃にはLVMHによる株式の大量取得に対抗したことも話題になった。\n服では意外な人選が続き、ウィメンズはエリック・ベルジェール（1980年代）、マルタン・マルジェラ（1997〜2003）、ジャン＝ポール・ゴルチエ（2003〜2010）、クリストフ・ルメール（2010〜2014）、ナデージュ・ヴァンヘ＝シビュルスキ（2014〜）、メンズはヴェロニク・ニシャニアンが1988年から37年間率い、2026年からグレース・ウェールズ・ボナーが継ぐ。\n古着では、マルジェラ期のウィメンズ（ダブルフェイスのコート、ロザンジュのスカーフ）が特に評価が高い。バッグは刻印（製造年を示す記号と職人の印）で製造年がわかる。カレは柄と年代の資料が多く、収集家も多い。",
