    "eras": [
      {
        "name": "ウィーン期",
        "from": 1977,
        "to": 1986,
        "d": "lang",
        "text": "ヘルムート・ラングがウィーンで自分の店とオーダーメイドの服づくりを始めた時代。独学で服を作り、知人やアーティストのための服から評判が広がった。\n1986年、パリのポンピドゥー・センターで行われたオーストリア文化の展示で服を発表し、これが実質的なパリ・デビューになった。この時代の服は古着ではほとんど見かけない。",
        "works": [
          "ウィーンのオーダーメイドの服（現存はごく少ない）"
        ]
      },
      {
        "name": "パリ期（ラング期前半）",
        "from": 1986,
        "to": 1997,
        "d": "lang",
        "text": "パリでコレクションを発表していた時代。黒・白・グレーを中心に、細身の仕立て、透ける素材の重ね着、ゴムやナイロンなど工業用の素材を組み合わせ、1990年代の「ミニマリズム」を代表するデザイナーになった。1987年にメンズを始める。\nTシャツやタンクトップの上にシアーなシャツやジャケットを重ねるスタイル、反射素材（リフレクティブ）やラバーコーティングなど、のちに多くのブランドがまねた手法がこの時代にほぼ出そろった。",
        "works": [
          "反射素材（リフレクティブ）のジーンズ（1994-95年秋冬ごろ）",
          "シアー（透ける）素材のシャツ・ドレスの重ね着",
          "ラバー・コーティングのコートやジャケット",
          "アーマー（防護）ベスト（1998年春夏メンズ）",
          "細身のブラックスーツ"
        ]
      },
      {
        "name": "ニューヨーク期（ラング期後半）",
        "from": 1998,
        "to": 2005,
        "d": "lang",
        "text": "1998年に拠点をニューヨークに移した時代。1998年秋冬はランウェイを行わず、CD-ROMとインターネットでコレクションを発表した。さらにヨーロッパより先に発表したことで、ニューヨークのコレクション日程が前倒しされるきっかけになった。\n1999年にはプラダ・グループが株式の過半を取得。ペンキが飛び散ったようなペインターデニム（1999年春夏）、ストラップやハーネス、シートベルトを使ったボンデージ調の服（2003-04年秋冬）など、現在のアーカイブ市場で最も人気の高い名作の多くがこの時代のもの。2005年にラングはブランドを離れ、のちにアーティストとして活動するようになった。",
        "works": [
          "ペインターデニム（1999年春夏）",
          "ボンデージストラップ／ハーネスのジャケット（2003-04年秋冬）",
          "アストロバイカー・ジャケット",
          "シアリングやフライトジャケットなどのアウター",
          "Helmut Lang Jeans のデニム"
        ]
      },
      {
        "name": "ポスト・ラング期",
        "from": 2006,
        "to": 2016,
        "d": "colovos",
        "text": "2006年に日本のリンク・セオリー（のちファーストリテイリング傘下）がブランドを取得し、ニューヨークを拠点に再出発した。マイケル＆ニコル・コロヴォス夫妻がデザインを担当し、ラング期のミニマルなイメージをもとにした、着やすいコンテンポラリーな服になった。古着では、ラング本人の時代とこの時代を区別することが特に大事。",
        "works": [
          "ドレープのあるジャージー素材のトップス",
          "レザーのライダース"
        ]
      },
      {
        "name": "再始動期",
        "from": 2017,
        "to": null,
        "d": "thomascawson",
        "text": "2017年に雑誌編集者のイザベラ・バーリーがエディター・イン・チーフに就き、シェイン・オリヴァー（Hood By Air）が「デザイナー・イン・レジデンス」として限定コレクションを手がけた。2018年からトーマス・カウソンのチーム、2023年にはピーター・ドゥがクリエイティブ・ディレクターになり、2024年に退任した。\nこの時代は、ラング期のアーカイブを復刻したり、ラング本人の作品や言葉を引用したりする動きもあった。",
        "works": [
          "ラング期のロゴやアーカイブの復刻アイテム"
        ]
      }
    ],
