        "d": "raf",
        "text": "家具デザインを学んだラフ・シモンズが、独学でメンズ服を始めた時代。細身のスーツ、学生服、ボーイスカウトのような制服、クラフトワークやニューウェーブの音楽など、若者文化（ユースカルチャー）をテーマにした。\n1997年からパリで発表。ショーには街で声をかけた少年たちをモデルに起用した。この時代の服は生産数が少なく、非常に高価で取引される。",
