    "summary": "ジル・サンダーが1968年にハンブルクで始めたブランド。上質な素材と無駄のない仕立てで1990年代ミニマリズムを代表した。Pradaの買収で創業者が2度去って2度戻り、ラフ・シモンズ（2005〜2012）、パリアルンガ、メイヤー夫妻と続き、2025年からシモーネ・ベロッティ。ユニクロとの「+J」でも知られる。",
    "about": "Jil Sander（ジル サンダー）は、ドイツのジル・サンダーが1968年にハンブルクのブティックから始めたブランド。繊維工学を学び、女性誌のファッションエディターを経て24歳でブティックを開いたサンダーは、1973年に最初のウィメンズのコレクションを発表した。\nジル・サンダーの服は、イタリアの機屋と開発した上質な素材（ウール、カシミア、コットン）、無駄のない仕立て、白、黒、ネイビー、キャメル、グレーの静かな色が特徴。キャメルのコート、白いシャツ、細身のパンツ、きちんとしたジャケットなど、仕事をする女性のための服で「ミニマリズムの女王」と呼ばれ、1990年代のファッションを代表した。1989年に上場し、1997年にメンズも始めた。香水やコスメでも成功した。\n1999年、Pradaグループが株式の75%を取得した。経営方針の違いから、創業者は2000年に退任、2003年に復帰して2004年に再び退任、2012年に再び復帰して2013年に3度目の退任をした。創業者の不在の間は、ミラン・ヴクミロヴィッチ（2000〜2002）、ラフ・シモンズ（2005〜2012）がデザインを担当した。ラフ・シモンズの時代は、ミニマリズムに鮮やかな色（2011年春夏のネオンカラーとボリュームのスカート）やクチュールの技術を持ち込み、高く評価された。\nその後、ロドルフォ・パリアルンガ（2014〜2017）、ルーシー&ルーク・メイヤー（2017〜2025）、シモーネ・ベロッティ（2025〜）と続いた。2021年からはOTBグループの傘下。\nラインには、セカンドラインの「Jil Sander Navy」（2011〜2019年）、ユニクロとの協業「+J」（2009〜2011年、2014〜2015年、2020年〜）がある。+Jのダウンジャケットやシャツは大ヒットし、今も古着で人気が高い。\n古着では、創業者の1990年代のコートやジャケット、ラフ期（2005〜2012）のメンズ・ウィメンズ、+Jの初期のアイテムが人気。創業者期・ラフ期・メイヤー期で、同じブランドでも空気感が大きく違うので、タグと年代で見分けることが大切。",
