    "summary": "イヴ・サンローランとピエール・ベルジェが1961年に設立。モンドリアン・ドレス、ル・スモーキング、サファリ・ジャケットで女性の服を変え、1966年にプレタポルテ「Rive Gauche」を始めた。トム・フォード、ピラーティ、エディ・スリマン（「Saint Laurent」表記に）、ヴァカレロと続き、2026年10月にヴァカレロが退任。",
    "about": "Saint Laurent（サンローラン）は、イヴ・サンローランと、実業家でパートナーのピエール・ベルジェが1961年に設立したメゾン。Diorの後継者として21歳で成功し、兵役をきっかけにDiorを去ったサンローランが、自分の名前で始めた。\nサンローランは、男性の服を女性の服に取り入れることで、女性の服を自由にした。1965年のモンドリアン・ドレス（画家モンドリアンの絵をそのままドレスにした）、1966年の女性のためのタキシード「ル・スモーキング」、1968年のサファリ・ジャケット（サハリエンヌ）とシースルーのブラウス、パンツスーツ、トレンチコート、ピーコートなど、今では当たり前の女性の服の多くがここから生まれた。1966年には、クチュールのメゾンとして初めてプレタポルテのブティック「Saint Laurent Rive Gauche（左岸）」を開き、若い女性が買える服を売った。1971年の1940年代を引用した「スキャンダルのコレクション」、1976年のバレエ・リュス、1977年の中国と香水「オピウム」、1979年のピカソへのオマージュなど、芸術や歴史への壮大なオマージュでも知られる。黒人やアジア人のモデルを積極的に起用した先駆者でもあった。\n1999年にGucciグループ（現Kering）がブランドを買収し、トム・フォードがプレタポルテのRive Gaucheを担当した（2001〜2004、モンバサ・バッグなど）。2002年に創業者が引退してクチュール部門は閉じた。その後、ステファノ・ピラーティ（2004〜2012）がアーカイブを知的に再解釈し、エディ・スリマン（2012〜2016）は表記を「Yves Saint Laurent」から「Saint Laurent」に変え、スタジオをロサンゼルスに移して、ロックやグランジのコレクションで売上を大きく伸ばした。アンソニー・ヴァカレロ（2016〜2026）は、1980年代風の大きな肩、極端に短いドレス、エッフェル塔の前でのショーで約10年率いた。\nメンズでは、1997〜1999年にエディ・スリマンがRive Gauche Hommeを立て直した時期もある。YSLのロゴ（1961年、カッサンドルのデザイン）も象徴的。\n古着では、Rive Gaucheの1970〜80年代の服、トム・フォード期の服とバッグ、エディ期（2012〜2016）のレザーのライダースジャケット、テディジャケット、細身のデニム、ブーツが人気。タグの表記（Rive Gauche、Yves Saint Laurent、Saint Laurent Paris）で年代がわかる。",
