    "summary": "子ども靴の店から始まったメゾン。フィービー・ファイロ期（2008〜2017）は「オールド・セリーヌ」と呼ばれ、今もアーカイブ人気が極めて高い。その後エディ・スリマン、マイケル・ライダーと続く。",
    "about": "Celine（セリーヌ）は、セリーヌ・ヴィピアナと夫のリシャールが1945年にパリで始めた、子ども用の注文靴の店から始まったメゾン。1960年代に女性用の靴、バッグ、服へと広がり、馬車のマークや凱旋門のチェーンのモチーフで、上品なブルジョワの女性のブランドとして知られた。\n1997年にLVMHが買収し、アメリカのマイケル・コースがプレタポルテを率いた（1997〜2004）。\n2008〜2017年のフィービー・ファイロの時代は、Celineの歴史で最も重要な時期とされる。ファイロは、上質な素材、無駄のない形、ゆったりしたパンツ、大きなコート、フラットな靴など、自分の人生を生きる知的な大人の女性のための服で、2010年代のファッションの女性像を定義した。顔のように見える「ラゲージ・トート」、翼のような「トラペーズ」、「ベルト・バッグ」、毛皮のついたサンダル（通称「ファーキンストック」）などがヒットし、広告で作家ジョーン・ディディオンを起用したことも話題になった。熱心なファンは「Philophiles」と呼ばれた。\n2018〜2024年はエディ・スリマンがアクサン（é）を外した「Celine」とし、ロックな服、細身のメンズ、凱旋門のロゴ「トリオンフ」を打ち出した。2025年からは、ファイロのもとで働いたマイケル・ライダーが率いている。\n古着では、フィービー期（2008〜2017）の服とバッグが「Old Céline」として非常に人気が高く、近年さらに価格が上がっている。アクサンのある「CÉLINE」のタグかどうかで年代がわかる。エディ期のメンズも人気。",
