    "archive": [
      "トム・フォード期（1994〜2004）の服はアーカイブとして根強い人気。特に1995〜1997年頃のベルベット、サテン、カットアウトのピース。",
      "ミケーレ期（2015〜2022）はマキシマリズムの象徴。古着としての評価も上がっている。",
      "同じGucciでもデザイナーごとに全く別のブランドのように見えるので、年代とデザイナーをセットで確認する。"
    ],
