    "summary": "クリストバル・バレンシアガがスペインで始め、1937年にパリへ。1968年に閉じたのち、ニコラ・ジェスキエールが再興し、デムナがストリートの頂点に押し上げた。2025年に就任したピッチョーリは約1年半で退任し、2026年11月からロンドンのマーティン・ローズ（かつてデムナのもとでメンズのコンサルタント）。",
    "about": "Balenciaga（バレンシアガ）は、スペイン・バスク地方出身のクリストバル・バレンシアガが1917年にサン・セバスティアンで始め、スペイン内戦を避けて1937年にパリのジョルジュ・サンク通りへ移したメゾン。\n創業者は、生地の裁断から縫製まですべての工程を自分でこなせる数少ないクチュリエで、ココ・シャネルに「本物のクチュリエは彼だけ」、クリスチャン・ディオールに「私たち全員の師」と言われた。肩や背中の線を立体的に操作し、身体から少し離れた服を作ることで、20世紀の女性のシルエットを変えた。バルーン・スカート、チュニック（1955年）、サック・ドレス（1957年）、ベビードール（1958年）、張りのあるガザール素材の「四次元」のドレス（1967年）などが代表作。スペインの闘牛士の衣装、宗教画、民族衣装も着想源だった。プレタポルテの時代の到来を受け入れられず、1968年にメゾンを閉じた。\n長い眠りの後、1990年代にジョゼフス・ティミスター（1992〜1997）がモダンな服で再出発させ、1997年に25歳のニコラ・ジェスキエールが就任した。ジェスキエールは、創業者のアーカイブを研究しつつ、未来的なシルエット、スポーツ素材、ネオプレン、パッチワーク、金色のロボットのレギンス（2007年春夏）などで、Balenciagaを最も先鋭的なブランドの一つにした。2001年の「モーターサイクルバッグ（City）」は大ヒットした。\nアレキサンダー・ワン（2012〜2015）を経て、2015〜2025年のデムナの時代は、巨大なショルダーのコート、オーバーサイズのパーカー、ダッドスニーカーの「トリプルS」（2017年）、ソックス型の「スピード・トレーナー」、IKEAのバッグに似たトート、Crocsとの協業、ビデオゲームでのコレクション発表、泥や吹雪のランウェイなど、挑発的で社会を映す演出で、ラグジュアリーとストリートの頂点に立った。2021年には1968年以来途絶えていたクチュールを再開した。ピエールパオロ・ピッチョーリ（2025〜2026）を経て、2026年11月からマーティン・ローズが率いる。\n古着では、ジェスキエール期（1997〜2012）の服とモーターサイクルバッグ、2000年代の靴、デムナ期のパーカーやスニーカーが人気。創業者の時代のクチュールは美術館級。",
