    "summary": "ユベール・ド・ジバンシィが1952年に設立。オードリー・ヘプバーンの映画の衣装で知られる。1995年の引退後はガリアーノ、マックイーン、ジュリアン・マクドナルド、リカルド・ティッシ（ロットワイラーやバンビの柄でストリートとラグジュアリーを結んだ）、クレア・ワイト・ケラー、マシュー・ウィリアムズと交代が続き、2024年からサラ・バートン。",
    "about": "Givenchy（ジバンシィ）は、ユベール・ド・ジバンシィが1952年に、24歳でパリに開いたメゾン。ジャック・ファット、ロベール・ピゲ、リュシアン・ルロン、エルザ・スキャパレリのもとで修業したジバンシィは、最初のコレクション「Les Séparables」で、組み合わせて着るセパレーツを提案し、モデルの名を取ったフリル袖の白いブラウス「ベッティーナ・ブラウス」で大評判となった。\n1953年に出会った女優オードリー・ヘプバーンとは40年以上にわたる友情を結び、彼女の私服と、『麗しのサブリナ』『パリの恋人』『ティファニーで朝食を』『シャレード』などの映画衣装を手がけた。『ティファニーで朝食を』の黒いドレスは、映画史上最も有名な服の一つとなった。ジャクリーン・ケネディ、グレース・ケリーらも顧客だった。敬愛するクリストバル・バレンシアガとは生涯親しかった。1988年にLVMHへ売却し、1995年に創業者が引退した。\nその後は交代が続き、ジョン・ガリアーノ（1995〜1996）、アレキサンダー・マックイーン（1996〜2001、白と金のクチュール「Search for the Golden Fleece」）、ジュリアン・マクドナルド（2001〜2004）が短期間で率いた。2005〜2017年のリカルド・ティッシの時代には、カトリックの宗教的なイメージ、ゴシック、ストリートやヒップホップを融合させ、ロットワイラー（2011年）やバンビ（2013年）のプリントのスウェット、ナイチンゲールやアンティゴナのバッグで、2010年代のラグジュアリー・ストリートを代表するブランドになった。\nクレア・ワイト・ケラー（2017〜2020、メーガン・マークルのウェディングドレス）、マシュー・ウィリアムズ（2020〜2023）を経て、2024年からサラ・バートンが率いている。\n古着では、ティッシ期のロットワイラーやバンビのスウェット、Tシャツ、アンティゴナのバッグ、マックイーン期の服が人気。",
