        "text": "2000年春夏にアーティストのジム・ダインと協業した。この頃から生産の一部がフランス、イタリア、チュニジア、ポルトガルにも広がった。2000年代は、レザーやレイヤードを使ったメンズが特に人気で、ロングブーツ、ラップパンツ、ドレープのカーディガンなどが定番になった。2013年、アンは引退した。",
