    "summary": "マルコム・マクラーレンとキングスロード430番地で始めた店からパンクの服を生み、のちに英国の伝統を引用した独自のスタイルへ。",
    "about": "Vivienne Westwood（ヴィヴィアン・ウエストウッド）は、ヴィヴィアン・ウエストウッドが1971年に、パートナーのマルコム・マクラーレンとロンドンのキングス・ロード430番地に開いた店から始まった。店名を「Let It Rock」（1950年代のテディ・ボーイの服）、「Too Fast to Live Too Young to Die」、「SEX」（1974年、ゴムやボンデージの服）、「Seditionaries」（1976年）と変えながら、ボンデージ・パンツ、安全ピンや破れたTシャツ、挑発的なスローガンのTシャツなどで、パンク・ファッションを作った。マクラーレンがマネージャーを務めたセックス・ピストルズの衣装も手がけた。1980年に店は「Worlds End」となり、今も同じ場所にある。\n1981年、ロンドンで最初の本格的なコレクション「Pirates」を発表し、海賊の服を着た新しいロマンティックなスタイルを作った。以後、ミニ・クリニ（短いクリノリン、1985年）、コルセット、ハリスツイード、タータン、18世紀の肖像画、王室や貴族の服など、英国の歴史と伝統を引用し、皮肉とユーモアを込めて再解釈した。土星の輪をつけた宝珠（オーブ）のロゴ（1980年代後半）、厚底の靴「ロッキンホース・バレリーナ」、指輪「アーマー・リング」、ナオミ・キャンベルがショーで転んだ超厚底の「スーパー・エレベーテッド・ギリー」（1993年）、パールのチョーカーなども知られる。\n1992年にOBE、2006年にDBE（デイム）を受けた。晩年は気候変動や環境問題、言論の自由のための活動家としても知られた。2016年から夫のアンドレアス・クロンターラーがメインラインを率い、2022年にヴィヴィアンは死去した。ラインは、Gold Label（メインライン）、Red Label、Anglomania、MANなど。\n古着では、1970年代のSEX・Seditionaries期の服（極めて高価、偽物も多い）、1980〜90年代のコルセット、ジャケット、オーブのジュエリー、2000年代のRed Labelの服が非常に人気。",
