    "summary": "2012年にハイデルベルクで始まったドイツのレーベル。歪んだ構造と手作業の染め・加工による新世代のアルチザン。現在はベルリンにアトリエとショールームを持つ。",
    "about": "Leon Emanuel Blanck（レオン エマニュエル ブランク）は、ドイツ出身のレオン・エマニュエル・ブランクが2012年にハイデルベルクで始めたブランド。ブランクは10代の頃からほぼ独学で服づくりとパターンを学んだ。\nブランクの服は、いったん服を分解して組み立て直したような構造、手作業による製品染めや加工で生まれる深い色と質感、手縫いの縫製、身体に沿う立体的なパターンが特徴。黒やグレー、生成り、土のような色の、レザー、リネン、コットン、ウールの服が多い。コレクションは「Distortion（歪み）」などの考え方で組み立てられ、自社の工房で多くの工程を行う。\nCarol Christian Poellの流れを汲む、アルチザン系の若い世代の代表とされ、パリで展示会を行っている。日本や海外のアルチザン系のファンから高い評価を受けており、生産数が少ないため古着でも高値で取引される。",
    "history": [
      {
        "year": 2012,
        "text": "ハイデルベルクにスタジオを開き、自身のレーベルを始める"
      },
      {
        "year": 2023,
        "text": "ベルリンに予約制のショールームを開く"
      }
    ],
