    "summary": "ジャンニ・ヴェルサーチが1978年に始めたミラノのメゾン。1997年のジャンニの死後は妹ドナテラが約28年率いた。2025年にPrada Groupが買収し、2026年7月からピーター・ミュリエがチーフクリエイティブオフィサー。",
    "about": "Versace（ヴェルサーチ）は、イタリア南部カラブリア州出身のジャンニ・ヴェルサーチが、兄サントとともに1978年にミラノで始めたブランド。仕立て屋の母の工房で育ったジャンニは、ミラノでComplice、Genny、Callaghanのデザイナーとして成功したのち、自身のブランドを立ち上げた。妹のドナテラも若い頃から協力した。\nVersaceの服は、ギリシャ神話の怪物メドゥーサの顔のロゴ、バロックの金の装飾の柄、鮮やかなプリント、金属を細かく織り込んだメタルメッシュ、身体を強調するボディコンシャスなシルエットで、1980〜90年代の華やかさと官能を象徴した。1991年秋冬のショーでは、ナオミ・キャンベル、シンディ・クロフォード、リンダ・エヴァンジェリスタ、クリスティ・ターリントンらを並べてジョージ・マイケルの曲に合わせて歩かせ、「スーパーモデル」の時代を作った。1994年に女優エリザベス・ハーレーが着た、安全ピンで留めた黒いドレスも有名。ダイアナ妃、エルトン・ジョン、マドンナら有名人との親交も深かった。\n1997年7月、ジャンニはマイアミの自宅前で射殺された。その後は妹のドナテラが約28年ブランドを率い、2000年のグラミー賞でジェニファー・ロペスが着たジャングル・プリントのドレスは、Googleの画像検索が作られるきっかけになったといわれる。\n2018年にMichael Kors（のちのCapri Holdings）、2025年にPradaグループが買収した。ダリオ・ヴィターレの短い在任を経て、2026年7月からピーター・ミュリエが率いる。セカンドラインに「Versus」「Versace Jeans Couture」などがある。\n古着では、1990年代のバロック柄のシルクのシャツ、デニム、メタルメッシュの服、メドゥーサのボタンのジャケットが非常に人気。",
