    "summary": "ローマの毛皮と革の店から始まったメゾン。カール・ラガーフェルドが1965年から2019年に亡くなるまで50年以上関わり、1997年にはシルヴィア・ヴェントゥリーニ・フェンディのバゲットが「イットバッグ」の時代を開いた。2025年からはマリア・グラツィア・キウリ。",
    "about": "Fendi（フェンディ）は、アデーレ・カサグランデと夫のエドアルド・フェンディが1925年にローマで始めた毛皮と革の店。2人の5人の娘（パオラ、アンナ、フランカ、カルラ、アルダ）が家業を継ぎ、ブランドを大きくした。\n1965年、姉妹は若いドイツ人デザイナー、カール・ラガーフェルドを迎えた。ラガーフェルドは2019年に亡くなるまで54年間Fendiの毛皮とウィメンズを手がけ、毛皮を軽く、染めたり穴をあけたり編んだりして遊び心のある素材に変えた。2つのFを組み合わせたロゴ「ズッカ柄」もラガーフェルドのデザインとされる。\n1997年、3代目のシルヴィア・ヴェントゥリーニ・フェンディが、小脇に抱えるフランスパンのような小さなバッグ「バゲット」をデザインした。ドラマ『セックス・アンド・ザ・シティ』で主人公キャリーが持ったことで世界的なヒットとなり、最初の「イットバッグ」と呼ばれた。2000年代には「スパイ・バッグ」、2010年代には「ピーカブー」、モンスターの顔の「バッグ・バグズ」もヒットした。\n2001年にLVMHの傘下に入った。ラガーフェルドの死後は、キム・ジョーンズがウィメンズとクチュール（2020〜2024）、シルヴィアがメンズとアクセサリーを担当し、2025年からマリア・グラツィア・キウリがチーフ・クリエイティブ・オフィサーを務める。ローマの「四角いコロッセオ」と呼ばれる建物が本社。\n古着では、1990年代〜2000年代前半のズッカ柄のバッグ、バゲット、毛皮のコートが人気で、Y2Kブームで再び注目されている。",
