    "summary": "ヴァレンティノ・ガラヴァーニが1959年にローマのコンドッティ通りで始めたクチュールメゾン。「ヴァレンティノ・レッド」と1968年の「ホワイト・コレクション」で知られる。創業者の引退後はファッキネッティ、キウリとピッチョーリ、ピッチョーリ単独（ピンクPP）を経て、2024年からアレッサンドロ・ミケーレ。創業者は2026年1月に死去。",
    "about": "Valentino（ヴァレンティノ）は、ヴァレンティノ・ガラヴァーニが1959年にローマのコンドッティ通りで始めたクチュールのメゾン。パリでジャン・デセ、ギ・ラロッシュのもとで修業したヴァレンティノは、1960年に出会ったジャンカルロ・ジャンメッティと公私にわたるパートナーとなり、ジャンメッティが経営を、ヴァレンティノがデザインを担った。\n1962年、フィレンツェのピッティ宮殿での発表で大成功を収め、国際的に知られるようになった。Valentinoの服は、深く鮮やかな赤「ヴァレンティノ・レッド」、繊細な刺繍、レース、リボン、ドレープのドレスで知られ、イタリアのエレガンスを代表した。1968年の白一色の「ホワイト・コレクション」ではVの金具を初めて使い、同年ジャクリーン・ケネディがオナシスとの結婚式で着たドレスも話題になった。エリザベス・テイラー、オードリー・ヘプバーン、ジュリア・ロバーツなど数多くの著名人に愛された。\n2008年に創業者が引退したのち、アレッサンドラ・ファッキネッティの短い在任を経て、マリア・グラツィア・キウリとピエールパオロ・ピッチョーリが共同クリエイティブディレクターとなった（2008〜2016）。2人は、ピラミッド型のスタッズを並べた「ロックスタッズ」の靴やバッグ（2010年）、ロマンティックで繊細なドレスで、ブランドを若い世代にも広げた。ピッチョーリ単独の時代（2016〜2024）は、大胆な色彩、多様なモデルの起用、2022年の蛍光ピンク「ピンクPP」で知られた。2024年からはアレッサンドロ・ミケーレが率いる。\n創業者は2026年1月に93歳で死去した。古着では、創業者期のドレスやクチュール、ガラヴァーニのラインの小物、ロックスタッズの靴が人気。",
