    "summary": "ピエール・バルマンが1945年にパリで開いたクチュールメゾン。2011年に25歳で就任したオリヴィエ・ルスタンが14年率い、2025年11月からアントナン・トロン。",
    "about": "Balmain（バルマン）は、ピエール・バルマンが1945年にパリのフランソワ1世通りに開いたメゾン。リュシアン・ルロンのもとでクリスチャン・ディオールと同僚だったバルマンは、細いウエストと豊かなスカート、上質な素材と刺繍で、「ジョリー・マダム（可愛い淑女）」と呼ばれる優雅な女らしさを打ち出した。キャサリン・ヘプバーン、ブリジット・バルドー、ソフィア・ローレン、タイ王妃シリキットらを顧客にし、舞台や映画の衣装も多く手がけた。1982年に創業者が亡くなると、エリック・モルテンセン、オスカー・デ・ラ・レンタらが率いた。\n2005〜2011年のクリストフ・デカルナンの時代、Balmainは大きく変わった。デカルナンは、極端に強調した肩のジャケット、軍服のような金ボタンのジャケット、スパンコールや刺繍の短いドレス、破れたデニムやスタッズで、ロックで攻撃的な女性像を打ち出し、2009年頃の「パワーショルダー」の流行を作った。\n2011年、25歳のオリヴィエ・ルスタンがクリエイティブディレクターに抜擢された。ルスタンは、カーダシアン家、ビヨンセ、リアーナ、ジジ・ハディッドら有名人を起用した「Balmain Army」、インスタグラムを使った発信、多様なモデルの起用、2015年のH&Mとの協業で、SNS時代の新しいラグジュアリーのあり方を示した。2025年にルスタンが退任し、Atleinのアントナン・トロンが後任となった。\n古着では、デカルナン期（2005〜2011）のパワーショルダーのジャケットや加工デニム、ルスタン期のビーズのジャケットが人気。",
