    "summary": "高田賢三が1970年にパリで始めたブランド。日本人デザイナーがパリで成功した先駆け。1993年にLVMH傘下となり、2010年代のタイガーのスウェットを経て、2021年からNIGOがアーティスティックディレクター。",
    "about": "KENZO（ケンゾー）は、日本人デザイナー高田賢三が1970年にパリのギャラリー・ヴィヴィエンヌに開いた小さなブティック「ジャングル・ジャップ」から始まったブランド。資金がなかった高田は、パリの市場で買った安い布を組み合わせて服を作り、店の壁にはアンリ・ルソーの絵のようなジャングルを描いた。\n高田の服は、色と柄を大胆に重ね、日本の着物、中国、インド、北欧、南米などの民族衣装を自由に混ぜた、ゆったりと動きやすいシルエットで、当時の窮屈なパリのモードに新しい風を吹き込み、雑誌『ELLE』の表紙を飾った。日本人デザイナーがパリで成功する道を最初に切り開いたブランドの一つとされる。1976年にブランド名を「KENZO」に変え、1983年にメンズ、1988年に香水（「花」をテーマにしたフローラルな香水は大ヒット）を始めた。\n1993年にLVMHに売却され、1999年に高田は引退した。その後、ジル・ロジエ、アントニオ・マラス（2003〜2011）を経て、Opening Ceremonyの創業者キャロル・リムとウンベルト・レオン（2011〜2019）が、虎の顔の刺繍のスウェット、目のモチーフ、映画監督との協業の映像で、Kenzoを若い世代の人気ブランドにした。フェリペ・オリヴェイラ・バプティスタ（2019〜2021）を経て、2021年からNIGOがアーティスティックディレクターを務め、ボケの花（ボケフラワー）のモチーフ、ヴィンテージのワークウェアの要素で、日本人として創業者のブランドを率いている。\n古着では、1970〜80年代の高田賢三期の服、2010年代の虎のスウェット、NIGO期のアイテムが人気。",
