    "summary": "ギャビー・アギョンが1952年に始め、高級プレタポルテを広めたメゾン。ラガーフェルド、ステラ・マッカートニー、フィービー・ファイロなど、若い才能の登竜門となってきた。",
    "about": "Chloé（クロエ）は、エジプトのアレクサンドリア出身のギャビー・アギョンが1952年にパリで始めたブランド。当時のパリでは、上質な服はオートクチュール（注文服）だけだったが、アギョンはクチュールの技術と素材で作る上質な既製服を目指し、「高級プレタポルテ（リュクス・プレタポルテ）」の先駆けとなった。1956年には、パリのカフェ・ド・フロールで最初のショーを開いた。\nChloéは、若いデザイナーを積極的に起用する伝統を持つ。カール・ラガーフェルド（1964年頃〜1983年、1992〜1997年）、ステラ・マッカートニー（1997〜2001）、フィービー・ファイロ（2001〜2006、パディントン・バッグ、ボーホー・シックの流行）、パウロ・メリム・アンダーソン（2006〜2008）、ハンナ・マクギボン（2008〜2011）、クレア・ワイト・ケラー（2011〜2017、ドリュー・バッグ）、ナターシャ・ラムゼイ＝レヴィ（2017〜2020）、ガブリエラ・ハースト（2020〜2023、サステナブル）と、のちに大物となるデザイナーが多くここを通った。\nChloéの一貫したイメージは、ボヘミアンで自由で、女性らしく、少し少女的な「Chloéガール」。透けるブラウス、フリル、レース、ゆったりしたドレス、ウェッジソールのサンダル、ブーツなどが象徴的。2024年から就任したシェメナ・カマリは、1970年代のChloéらしさを取り戻し、「ボーホー・シック」の再流行を作った。\n古着では、1970年代のラガーフェルド期のドレス、2000年代のフィービー期の服とパディントン・バッグ、2010年代のドリュー・バッグが人気。",
