    "summary": "ティエリー・ミュグレーが1973年に「Café de Paris」コレクションで始めたブランド。誇張した肩とウエスト、彫刻的なボディのシルエットで1980〜90年代を象徴し、近年アーカイブ人気が再燃している。",
    "about": "Mugler（ミュグレー）は、フランスのストラスブール出身のティエリー・ミュグレーが1973年に「Café de Paris」の名で始め、1974年に自身の名前にしたブランド（1973年とする資料もある）。ミュグレーは14歳からストラスブールのオペラ座のバレエ団で踊りながら服を作っていた。\nミュグレーの服は、極端に強調した肩と細く絞ったウエスト、昆虫やロボット、クロム仕上げの車のボディを思わせる金属やビニールのボディースーツ、ハリウッドの女優やSFのヒロインのような力強い女性像で、1980〜90年代のファッションを代表した。ショーそのものも、数千人の観客を集めた1984年の10周年のショー、1995年の20周年のショーなど、演劇やコンサートのような大スペクタクルだった。1992年の香水「エンジェル」は、星型のボトルと甘いグルマン系の香りの先駆けとして大ヒットした。\n2002年にミュグレーは服づくりを離れ、ブランドは香水を中心に続いた。ニコラ・フォルミケッティ（2010〜2013、レディー・ガガとの関わり）を経て、2017〜2025年のケイシー・キャドワラダーの時代に、伸縮するメッシュのボディースーツやカットアウトの服が、ベラ・ハディッド、ドージャ・キャット、ビヨンセらに着用され、コロナ禍にはショーの代わりに凝った映像作品で発表して、SNS時代のMuglerとして再び大人気となった。2019年からは創業者の大規模な回顧展「Thierry Mugler: Couturissime」が世界を巡回した。2025年からミゲル・カストロ・フレイタスが率いる。\n古着では、1980〜90年代の構築的なジャケット、スーツ、ドレスが非常に人気で、セレブリティがアーカイブを着ることでも注目されている。",
