    "summary": "ブルガリア出身のキコ・コスタディノフがロンドンで2016年に始めたブランド。作業着を下敷きにした緻密なパターンと、ASICSとの協業スニーカーで知られる。",
    "about": "Kiko Kostadinov（キコ コスタディノフ）は、ブルガリアのソフィア出身のキコ・コスタディノフが2016年にロンドンで始めたブランド。16歳でイギリスに移住したコスタディノフは、セントラル・セント・マーチンズで学び、在学中の2014年にStüssyとのカプセル・コレクションを手がけて注目された。\nKiko Kostadinovの服は、作業着、制服、医療用の服、スポーツウェアのディテールを、何層にも切り替えた複雑なパターンで組み替え、機能的でありながら未来的なメンズを作る。落ち着いた色に鮮やかな差し色を入れる色使いも特徴。2018年からは、双子のデザイナー、ローラとディアナ・フェルナーとともにウィメンズも手がけている。\nASICSとの協業スニーカーは大ヒットし、スニーカーのデザインの新しい流れを作った。2017年から約2年、Mackintoshの「0001」ラインのクリエイティブディレクターも務めた。Camperとの協業でも知られる。\n古着では、ASICSとの協業スニーカー、作業着の再構築のジャケットやパンツが人気。",
