    "summary": "山本寛斎のブランド。歌舞伎や武者絵など日本の伝統的なモチーフを大胆なグラフィックにし、1971年に日本人として初めてロンドンでショーを開いた。デヴィッド・ボウイがジギー・スターダスト期に着たことで世界的に知られる。",
    "about": "KANSAI YAMAMOTO（カンサイ ヤマモト）は、山本寛斎が1971年に始めたブランド。同年、日本人として初めてロンドンでファッションショーを開き、世界的に注目された。\n山本寛斎の服は、歌舞伎、浮世絵、武者絵、祭り、火消しの半纏など日本の伝統文化を、原色の強い色、大胆な柄、立体的でボリュームのあるシルエットで表現したもの。西洋のモードの洗練とは対極にある「派手さ」と「力強さ」が特徴で、ロンドン、パリ、ニューヨークのコレクションで発表した。\nデヴィッド・ボウイがジギー・スターダストのツアー（1972〜73年）で着た、縞模様のジャンプスーツ、歌舞伎の早変わりの手法を取り入れた衣装などは、ロックの歴史に残る衣装となった。\n1990年代以降は、服のコレクションよりも、数万人の観客を集める大規模なイベント「KANSAI SUPER SHOW」（モスクワの赤の広場など）のプロデュースに軸足を移した。2020年に山本は死去した。近年、ボウイの衣装やアーカイブが海外で再評価され、1970年代の服は非常に高値で取引されている。",
    "history": [
      {
        "year": 1971,
        "text": "ロンドンで「KANSAI IN LONDON」を開き、日本人として初めてロンドンでコレクションを発表。ボウイが作品「因幡の素兎」を個人的に購入しステージ衣装に"
      },
      {
        "year": 1973,
        "text": "ボウイのジギー・スターダスト期のツアー衣装を手がける（袴の形のジャンプスーツ、「出火吐暴威」のマントなど）"
      },
      {
        "year": 2020,
        "text": "7月21日、山本寛斎が76歳で死去"
      }
    ],
