    "summary": "独学で服づくりを学んだ山下隆生のブランド。アニメなどのポップカルチャーとモードを結びつけた先駆けで、1990年代の東京を代表する。近年再始動し、90年代リバイバルの源流として再評価されている。",
    "about": "beauty:beast（ビューティービースト）は、独学で服づくりを学んだ山下隆生が1990年に前身を始めたブランド。\nbeauty:beastの服は、日本のアニメやキャラクター、ポップカルチャー、SFのイメージを大胆にグラフィックとして使い、パッチワークや再構築、異素材の組み合わせと合わせた、1990年代の東京らしい自由で遊び心のあるもの。アニメとハイファッションを結びつけた先駆者とされ、のちの日本のブランドがアニメと協業する流れの原点の一つといえる。\n1990年代の東京のストリートとモードの境界で、雑誌や若者に熱心に支持され、パリでも展示会を行った。1990年代の日本のブランド（いわゆる「Japanese archive」）への関心が海外で高まる中で、近年は海外のアーカイブ・コレクターからも再評価され、当時の服が高値で取引されている。",
