    "summary": "古着店「go-getter」の立ち上げに関わった尾花大輔のブランド。古着やミリタリー、ワークウェアを研究し、現代的なサイズ感に作り直す。名前はロサンゼルスのノースハリウッドに由来し、綴りを言葉遊びで変えた。",
    "about": "N.HOOLYWOOD（エヌ・ハリウッド）は、古着店「go-getter」の立ち上げに関わった尾花大輔が2001年に始めたブランド。尾花は古着のバイヤーとしてアメリカで仕入れを担当した経験を持ち、2000年に開いた店「ミスターハリウッド」がブランドの母体となった。\nN.HOOLYWOODの服は、古着や軍服、ワークウェアを徹底的に研究し、そのディテール（ポケット、ステッチ、裏地、ボタンの付け方など）や構造を、現代的なサイズ感とシルエットに落とし込んだメンズで知られる。毎シーズン、アメリカの歴史、人物、風景、職業などをテーマにし、そのテーマから服を組み立てる。\n2002年から東京でショーを行い、2010年頃からはニューヨーク・ファッションウィークで発表している。Champion、Wrangler、Wildthings、Dickiesなどアメリカのブランドとの協業も多い。古着に深い愛情を持つブランドとして、古着好きにも支持されている。",
