    "summary": "セレクトショップNEPENTHESを1988年に創業した清水慶三が1995年に始めたブランド。古着やアメリカンカジュアルに独特の美学を加えた服で、蝶（パピヨン）の刺繍のトラックパンツが代表作。",
    "about": "NEEDLES（ニードルズ）は、1988年にセレクトショップ「NEPENTHES（ネペンテス）」を創業した清水慶三が、1995年に始めたオリジナルのブランド。NEPENTHESは、アメリカの古き良きワークウェアや、日本ではまだ知られていなかったブランドを紹介し、1990年代の東京のアメカジやワークウェアのブームに大きな影響を与えた。\nNEEDLESの服は、アメリカの古着やワークウェア、ミリタリーを独自に解釈し、刺繍やパッチワーク、民族的な要素を加えたもの。蝶（パピヨン）の刺繍のついたトラックパンツやトラックジャケットは、NEEDLESの代名詞となり、2010年代後半には海外でも大流行した。古着のフランネルシャツなどを切り分けて組み合わせ直すリメイクのライン「Rebuild by Needles」も人気。\nネペンテスの系列には、ニューヨークで鈴木大器が始めたEngineered Garments、South2 West8（アウトドアと釣りのライン）などのブランドがある。古着好き、アメリカの服好きの間で長く支持されている。",
