    "summary": "元Jリーガーの森敦彦と石塚啓次が2005年に始めたブランド。音楽、映画、アートを背景にした柄シャツやグラフィックで知られる。旗艦店は東京・東山の「PARADISE TOKYO」（2015年）。",
    "about": "WACKO MARIA（ワコマリア）は、元Jリーガーの森敦彦と、同じく元Jリーガーの石塚啓次が2005年に設立したブランド。東京・中目黒の店「PARADISE TOKYO」を拠点にしている。\nWACKO MARIAの世界観は、アウトローで色気のある、大人の不良の服。ハワイアンシャツ（アロハシャツ）、レーヨンのシャツ、レオパード柄、レゲエやジャズ、ソウル、ロックなどの音楽、映画、裸の女性やタトゥー、マリア像などの宗教的なモチーフのグラフィックを、上質な素材で作る。\n音楽と映画への愛が深く、ジャズのレコードのジャケット、映画のポスター、ミュージシャンやアーティストとのコラボレーションのアロハシャツは、毎シーズン人気を集める。国内外で人気を集め、海外にも店舗を広げている。",
