    "summary": "古田泰子が1997年に始めたブランド。異素材や古着的な要素を組み合わせる「ハイブリッド」な構成で、ロンドンやパリでも発表してきた。",
    "about": "TOGA（トーガ）は、古田泰子が1997年に始めたブランド。文化服装学院を卒業後、舞台などの衣装の仕事を経験した古田の服は、衣装のような大胆さと日常の服を併せ持つ。\nTOGAの服は、異なる素材の組み合わせ、ウエスタンのディテール（ウエスタンブーツ、メタルのパーツ、フリンジ、コンチョ）、ヴィンテージの要素、透ける素材を、少しずらしたバランスで使い、強くて少し奇妙な女性像を作る。日本の古いものや、海外の民族衣装も着想源となる。\n2006年からパリ・コレクションに参加し、2011年頃からはロンドン・コレクションで発表している。メンズの「TOGA VIRILIS」、セカンドラインの「TOGA PULLA」、靴やアクセサリーも人気で、ウエスタンブーツ、メタルのバックルのベルト、メタルのパーツのついたサンダルは定番となった。H&M、Dickiesなどとの協業でも知られる。",
