    "summary": "黒河内真衣子が2010年に始めたウィメンズ。日本各地の工芸や素材を研究し、繊細なテキスタイルで表現する。",
    "about": "Mame Kurogouchi（マメ クロゴウチ）は、三宅デザイン事務所出身の黒河内真衣子が2010年に始めたウィメンズのブランド。「Mame」は黒河内の子どもの頃からのあだ名。\nMame Kurogouchiの服は、日本の工芸や手仕事、竹籠や陶器、着物の文様、故郷の長野の自然、身近な風景や家族の記憶から着想した、繊細で詩的なもの。レースや刺繍、透ける素材、立体的な織り、かぎ針編みを重ね、日本の産地の職人と開発した素材を多く使う。コレクションごとに一冊の本のような物語がある。\n2016年に毎日ファッション大賞の新人賞を受賞し、2018年からパリ・コレクションで発表している。ユニクロとの協業では、透けるインナーやニットが大ヒットした。日本の工芸を現代の女性の服にするブランドとして、国際的に評価されている。",
