    "summary": "森永邦彦が2003年に始めたブランド。名前は「A REAL（日常）」「UN REAL（非日常）」「AGE（時代）」から。光で色が変わる素材など、テクノロジーを使った服づくりで知られ、2019年にLVMHプライズのファイナリスト。",
    "about": "ANREALAGE（アンリアレイジ）は、森永邦彦が2003年に始めたブランド。名前は、「A REAL（日常）」「UN REAL（非日常）」「AGE（時代）」を組み合わせたもの。\n初期は、細かい布をつなぎ合わせたパッチワークの服で知られた。2010年代からは、テクノロジーと服の関係を問うコンセプチュアルなコレクションで注目された。人体ではなく球体や三角錐、立方体に合わせて服を作る「〇△□」（2009年）、極小と極大のサイズの服、光に当たると色が変わるフォトクロミック素材の服、カメラのフラッシュを当てると模様が浮かぶ服、デジタルの映像と連動する服など、「見る」ことと「着る」ことを問い直す作品を発表している。\n2014年からパリ・コレクションに参加し、2019年にLVMHプライズのファイナリストとなった。2021年にはFendiとの協業も話題になった。ドラマや映画、アーティストの衣装も多く手がけている。",
