    "about": "AURALEE（オーラリー）は、岩井良太が2015年に始めたブランド。\nAURALEEの服づくりの特徴は、素材をゼロから作ること。オリジナルの糸を開発し、日本の機屋と生地を織り、軽くて柔らかく、上質な素材で、シャツ、ニット、コート、スラックス、Tシャツなどのベーシックな服を作る。淡い色やくすんだ色の繊細な組み合わせ、ゆったりとした着心地の良さで、国内外に熱心なファンを持つ。\n2019年からパリ・コレクションでショーを行い、New Balanceとのスニーカーの協業も人気を集めた。「静かなラグジュアリー」の流れの中で、日本の素材の良さを世界に伝えるブランドとして高く評価されている。",
