    "summary": "堀川達郎が2001年に東京で始めたレーベル。服のラインは2004年から。黒を中心にしたダークで細長いシルエットのメンズ。",
    "about": "JULIUS（ユリウス）は、堀川達郎が2001年に東京で始めたレーベル。当初はアートやグラフィック、音楽を含むプロジェクトとして始まり、のちに服のブランド「JULIUS_7」として展開した。\nJULIUSの服は、黒を中心にしたダークな色、構築的でありながらドレープのあるシルエット、レイヤードを前提にした長い丈のトップス、細身のパンツ、レザーやデニムの加工などで、日本のアヴァンギャルド系、ゴシック系、サイバー系を代表するブランドの一つ。堀川が影響を受けたインダストリアル、ノイズ、エレクトロニックの音楽が、ブランドの世界観の土台にある。\n2006年頃からパリでも展示会やショーを行い、海外にもファンを持つ。服だけでなく、ブランドの世界観を表現する写真や映像、音楽にもこだわっている。古着では、2000年代後半〜2010年代のレザーのジャケット、加工したデニム、長いカットソーが人気。",
