    "about": "DEVOA（デヴォア）は、西田大介が2008年頃に始めたブランド。西田は、若い頃にレスリングに打ち込み、その後医療の道を学んだという、ファッションデザイナーとしては異色の経歴を持つ。人体の構造や動き、筋肉や骨格の知識が、服づくりの土台になっている。\nDEVOAの服は、人体の構造と動きの研究にもとづく立体的なパターン、身体に沿いながら動きを妨げないシルエット、製品染めや天然素材による深い色と質感が特徴。黒やグレーを中心にしたストイックな服で、レザー、リネン、ウールなどの素材を使う。\n日本のアルチザン系として、The Viridi-anneやJULIUSなどとともに国内外のファンに支持されている。",
