    "summary": "アントワープの次の世代を代表するデザイナー。メランコリックで少女的なウィメンズ。2009年に経済危機で一度閉じ、2012年に再始動したが、2017-18年秋冬を最後に再び休止した。",
    "about": "Veronique Branquinho（ヴェロニク ブランキーニョ）は、ベルギーのフィルフォールデでポルトガル系の家庭に生まれたヴェロニク・ブランキーニョが、1998年にパリで発表したブランド。アントワープ王立芸術アカデミーを1995年に卒業したブランキーニョは、アントワープ・シックスの次の世代を代表するデザイナーとなった。\nブランキーニョの服は、メランコリックで少女的、しかしストイックで知的な女性像を持つ。くすんだ色（グレー、ベージュ、黒、ボルドー）、長いプリーツのスカート、細身のジャケット、ハイネックのニット、学校の制服やカトリックの服を思わせるディテールで、1990年代末から2000年代の「アントワープの静かな美しさ」を体現した。2003年にはメンズも始め、ベルギーの革製品の老舗Delvauxのバッグのデザインにも関わった。\n2009年にブランドを休止し、2012年に再開したが、2017年に再び休止した。古着では、2000年代前半のニット、スカート、コートが根強い人気を持つ。",
    "history": [
      {
        "year": 1998,
        "text": "自身のレーベルを始める（1997年とする資料も）"
      },
      {
        "year": 2009,
        "text": "経済危機により閉鎖"
      },
      {
        "year": 2012,
        "text": "オンワードの支援で再始動（2013年春夏から）"
      },
      {
        "year": 2017,
        "text": "2017-18年秋冬のショーを最後に再び休止"
      }
    ],
