    "summary": "フランコ・モスキーノが1983年に始めたブランド。ファッションそのものを皮肉るユーモアとポップなモチーフで、1980〜90年代を象徴した。ジェレミー・スコットの10年を経て、2023年以降は交代が続いている。",
    "about": "Moschino（モスキーノ）は、ミラノのブレラ美術アカデミーで絵画を学び、ジャンニ・ヴェルサーチのもとでイラストレーターとして働いたフランコ・モスキーノが、1983年に始めたブランド。\nモスキーノは、ファッションの世界そのものを皮肉るユーモアとパロディで知られた。「Expensive jeans（高いジーンズ）」「Cheap and Chic（安くてシック）」「Stop the Fashion System（ファッション・システムを止めろ）」などのスローガンを刺繍したジャケット、シャネルのツイードのスーツのパロディ、ハートやピースマーク、テディベア、食べ物のモチーフ（目玉焼き、オリーブ）、疑問符やドル記号のボタンなどで、1980〜90年代の高級ブランドの権威や消費主義をからかった。1988年にはセカンドライン「Cheap and Chic」、のちにジーンズのライン「Moschino Jeans」なども始めた。環境保護や動物愛護、エイズ問題のメッセージも積極的に発信した。\n1994年9月にフランコが44歳で亡くなった後は、長年のアシスタントだったロッセラ・ヤルディーニがブランドを率いた（1994〜2013）。2013年からはアメリカのジェレミー・スコットがクリエイティブディレクターとなり、マクドナルドのロゴ、バービー人形、スポンジ・ボブ、ルーニー・テューンズ、ガソリンスタンドなど、ポップカルチャーの記号を大胆に引用した服とバッグで、フランコのユーモアの精神をSNS時代に受け継いだ。\n2023年にスコットが去った後は、ダヴィデ・レンネ（就任から約10日で急逝）、アドリアン・アッピオラーザ（2024〜2026）と交代が続いている。親会社はイタリアのAeffe。\n古着では、1980〜90年代のフランコ期のスローガン入りのジャケット、パロディの服、ハートのモチーフのアイテム、ジェレミー・スコット期のバッグが人気。",
