    "summary": "ジャック・マッコローとラザロ・ヘルナンデスが2002年に始めたブランド。2人は2025年にLoeweのクリエイティブディレクターへ移り、Proenza Schoulerはレイチェル・スコットが率いる。",
    "about": "Proenza Schouler（プロエンザ スクーラー）は、ニューヨークのパーソンズ美術大学の同級生、ジャック・マッコローとラザロ・ヘルナンデスが2002年に始めたブランド。名前は、2人の母の旧姓（プロエンザとスクーラー）を組み合わせたもの。2人で共同制作した卒業コレクションを、ニューヨークの百貨店Barneysが全点買い取り、卒業と同時にブランドを立ち上げた。\nProenza Schoulerの服は、アメリカらしいスポーティーさと、テクニカルな素材、アートやクラフト、グラフィックの要素を融合したもの。2004年にCFDAの新人賞を受賞し、その後もCFDAのウィメンズウェア・デザイナー・オブ・ザ・イヤーを何度も受賞した。2008年に発表したサッチェル型のバッグ「PS1」は大ヒットし、2000年代後半のイットバッグとなった。\n2011年にValentinoの親会社が出資したが、2018年に投資家とともに株式を買い戻し、経営の自由を取り戻した。\n2025年、2人はLoeweの共同クリエイティブディレクターに就任し、Proenza Schoulerは、ジャマイカ出身のデザイナー、レイチェル・スコット（Diotima）に託された。\n古着では、PS1バッグ、2000年代後半〜2010年代のプリントのドレスやニットが人気。",
    "history": [
      {
        "year": 2002,
        "text": "マッコローとヘルナンデスが創業"
      },
      {
        "year": 2018,
        "text": "個人投資家とともに株式を買い戻し、経営権を取り戻す"
      },
      {
        "year": 2025,
        "text": "2人がLoeweへ。レイチェル・スコットがクリエイティブディレクターに（初コレクションは2026年）"
      }
    ],
