    "summary": "山本耀司のもとで学んだエンニオ・カパサが、兄と1986年にミラノで始めたブランド。黒を中心にしたロックなミニマリズムで、90年代のミラノで人気を集めた。",
    "about": "Costume National（コスチューム・ナショナル）は、エンニオ・カパサが兄のカルロとともに、1986年にミラノで始めたブランド。\nエンニオは、1980年代前半に東京で山本耀司のもとで働いた経験から、黒の美しさや、装飾をそぎ落とした服づくりを学んだ。そこにロックやパンクの雰囲気、細身のシルエット、レザーを加え、1990年代のミラノで、プラダやジル・サンダーとはまた違う「ロックなミニマリズム」として人気を集めた。1993年からパリで発表し、のちにミラノに戻った。\nメンズでは、細身のスーツ、レザーのライダース、ブーツなどが特に人気で、エディ・スリマンのディオール・オム以前の「細いロックの服」の流れを作ったブランドの一つとされる。カジュアルラインの「C'N'C」も展開した。\n2016年にエンニオが離れたあと、ブランドの活動はほぼ止まった。1990年代〜2000年代のメンズのレザーやテーラードは、アーカイブとして再評価されている。",
