    "summary": "クロード・モンタナが1979年にパリで始めたブランド。大きく張った肩と細いウエスト、レザーの服で、80年代の「パワー・ショルダー」を代表した。",
    "about": "Claude Montana（クロード・モンタナ）は、パリ生まれのクロード・モンタナが1979年に始めたブランド。\nモンタナはレザーの会社でデザイナーとして働いた経験を生かし、レザーを大胆に使った服を作った。極端に大きく張り出した肩、細く絞ったウエスト、彫刻のようなシルエットは、1980年代の「パワー・ショルダー」を代表するスタイルになり、同じ時代のティエリー・ミュグレーとともに、80年代のパリのファッションを象徴した。1981年にメンズの「モンタナ・オム」を始めた。\n1990〜1992年にはランバンのオートクチュールも担当し、フランスのクチュールの賞である「金の指ぬき賞」を2度受けた。しかしその後、私生活の悲劇や経営の問題が重なり、1990年代後半にブランドの経営権を失った。\n2024年2月にモンタナが亡くなり、80年代のレザーや肩の大きなジャケットが、アーカイブとして改めて注目されている。古着では、レザージャケット、肩の大きなコート、モンタナ・オムのブルゾンなどが見つかる。",
