    "summary": "マルティーヌ・シットボンが1986年にパリで始めたブランド（〜2004年）。ロック、70年代、ユニセックスのテーラードをまぜ、90年代のパリで評価された。",
    "about": "Martine Sitbon（マルティーヌ・シットボン）は、カサブランカ生まれでパリ育ちのマルティーヌ・シットボンが、1986年に始めたブランド。\nシットボンは、ロック、1970年代、ユニセックスなテーラード、くすんだ色、ベルベットやサテンなどの素材を組み合わせ、きれいすぎない、少し退廃的な雰囲気の服を作った。1988年から約4年半はクロエのデザインも担当し、クロエに若々しいロックの空気を持ち込んだ。\n1990年代のパリでは、グランジやロックの空気を表すブランドとして、音楽やアートの世界の人たちにも支持された。写真家やミュージシャンとの協業も多かった。\n自分の名前のブランドは2004年に終わり、2006年からは新しいブランド「ルー・デュ・メイル（Rue du Mail）」を2013年まで続けた。1990年代のシットボンの服は、流通は少ないが、アーカイブ市場で静かに人気がある。",
