    "summary": "カルペ・ディエムに関わったルカ・ラウリーニが始めたイタリアのブランド。手作業のニットウェアで知られる、アルチザン系の定番。",
    "about": "Label Under Construction（ラベル・アンダー・コンストラクション）は、イタリアのデザイナー、ルカ・ラウリーニのブランド。\nラウリーニは、マウリツィオ・アルティエリのカルペ・ディエムの仕事に関わり、イタリアのアルチザン系の服づくりを学んだ。その後、自分のブランドとして、主にニットウェアを中心にしたコレクションを始めた。\n柔らかいウールやカシミア、リネンなどを使い、手作業の縫製、ほつれや縫い目を見せる仕上げ、着るほどに体になじむ形のニットやカットソーを作る。ブランド名のとおり「作りかけ」のような、完成しすぎない雰囲気が特徴。\nカルペ・ディエムから広がったイタリアのアルチザン系ブランド（m.a+、CCP など）と一緒に語られることが多く、レイヤードの基本になるニットとして人気がある。",
