    "about": "Isaac Sellam Experience（アイザック・セラム エクスペリエンス）は、フランスのデザイナー、アイザック・セラムが2002年にパリで始めたブランド。\nセラムは革職人として経験を積み、上質なレザーやワニ、トカゲなどのエキゾチックレザーを使ったジャケット、コート、ブーツを作っている。裏地をつけずに革一枚で仕立て、染めや洗いで、使い込んだような柔らかく軽い風合いに仕上げるのが特徴。\nアルチザン系の中でも、レザージャケットのブランドとして根強い人気があり、日本でもアルチザン系の専門店で扱われている。体に沿う細身のシルエットと、独特なパターンのライダースが代表的。",
