    "about": "KMRii（ケムリ）は、デザイナーの内瀬輝樹が、インドネシアのバリ島で2000年に始めたブランド。\n内瀬はメキシコでジュエリーづくりと革小物の技術を学び、バリに移り住んで、現地の職人とともに、バッグや革小物、レザーアクセサリーを作り始めた。民族的なモチーフ、手作業の革の加工、ロックな雰囲気を組み合わせたアイテムは、2000年代の日本で、ロック系・ビジュアル系のファッションとともに人気を集めた。\nのちに内瀬は「14th Addiction」も始めた。2000年代の日本のロック系・Y2K 系のファッションへの関心の高まりで、近年は海外の古着市場でも再評価されている。",
