    "about": "14th Addiction（フォーティーンス・アディクション）は、KMRii のデザイナー、内瀬輝樹が2007年に始めた日本のブランド。\nビジュアル系の音楽シーンとつながる、ダークでロックなスタイルで知られる。レザー、ダメージ加工、レイヤード、シルバーのアクセサリーを組み合わせた服は、2000年代後半の日本のロック系ファッションの一部として人気を集めた。\nその後、内瀬が約6年の休止期間をとったためブランドは静かになったが、2023年に再始動し、レザーグッズ、靴、アウター、パンツを中心にしている。近年は、2000年代の日本のブランドへの関心（Japanese archive）の高まりで、海外でも注目されている。",
