    "summary": "佐藤信彦がデザインした東京のブランド。手作業で加工したロックなデニムやレザーで、1990年代後半〜2000年代の原宿で人気。Japanese archive の代表格。",
    "about": "L.G.B.（ル・グラン・ブルー）は、デザイナーの佐藤信彦が手がけた東京のブランド。1990年代後半（1999年ごろ）に始まったとされる。\n佐藤はミュージシャンとしても活動しており、ロックやバイカーのイメージを、手作業で加工したデニム、レザー、ニットに落とし込んだ。強いダメージ加工、ペイント、スタッズ、細身のシルエットは、1990年代後半から2000年代の原宿のロック・ファッションの中で人気を集めた。\n運営会社は「マニアック・コーポレーション」で、同じ会社のブランドに「イフ・シックス・ワズ・ナイン（ifsixwasnine）」がある。ifsixwasnine も、ロックな加工のデニムやレザーで知られる。\n近年は、海外で2000年代の日本のロック系ブランドが「Japanese archive」として非常に人気になり、L.G.B. や ifsixwasnine のデニム、レザー、ニットは高値で取引されるようになった。",
